ass="col-place isle untaught"><circle class="pip" cx="52" cy="376" r="4"/><text class="name" x="52" y="366.4" style="font-size:10.3px;text-anchor:middle">The Primer</text></g><g class="col-next"><circle class="ring-a" cx="319.8" cy="214.4" r="8.3"/><circle class="ring-b" cx="319.8" cy="214.4" r="8.3"/><text transform="translate(326.8 220.9) rotate(43)" text-anchor="start" dy="0.36em">&#x261C;</text></g><g class="col-rose" transform="translate(542 384)"><circle r="12"/><path d="M0 -12 L2.8 -2.8 L12 0 L2.8 2.8 L0 12 L-2.8 2.8 L-12 0 L-2.8 -2.8 Z"/><text y="-16">N</text></g><text class="col-title" x="23" y="400">A Chart of the Lessons</text></svg>","card":"","caption":"","seat":"head","cardLeft":"0","cardTop":"0","foldWidth":"40rem"};
