.col-night .col-sea{fill:none;stroke:rgb(from var(--line-tan) r g b / .35);stroke-width:5}
.col-night .col-land{fill:rgb(from var(--parchment) r g b / .1);stroke:var(--line-tan);stroke-width:1.1}
